:root{--green:#18c47b;--deep:#111827;--panel:#17233d;--card:#1c3154}*{box-sizing:border-box}body{margin:0;overflow:hidden;background:var(--deep);color:#fff;font-family:Inter,ui-sans-serif,system-ui}.pos{display:flex;height:100vh}.catalog{display:flex;min-width:0;flex:1;flex-direction:column;background:linear-gradient(145deg,#16213e,#101827)}.top{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff15;background:linear-gradient(100deg,#10b981,#0ea569);padding:12px 20px}.brand{display:flex;align-items:center;gap:10px}.brand-icon{display:grid;height:38px;width:38px;place-items:center;border-radius:12px;background:#ffffff25;font-size:22px}.brand b{display:block;font-size:16px}.brand small{font-size:11px;opacity:.8}.top-right{display:flex;align-items:center;gap:10px;font-size:12px}.top-right .user{border-radius:999px;background:#ffffff20;padding:7px 12px}.back{border:1px solid #fff7;border-radius:9px;padding:7px 10px;color:#fff;text-decoration:none}.tools{display:flex;gap:10px;border-bottom:1px solid #ffffff10;background:#111827;padding:12px 16px}.search{min-width:0;flex:1;border:1px solid #ffffff10;border-radius:10px;background:#17233d;padding:11px 14px;color:#fff;outline:0}.search:focus{border-color:var(--green);box-shadow:0 0 0 3px #18c47b20}.clear-search{margin-left:-47px;border:0;background:none;color:#9aa6b8;cursor:pointer}.categories{display:flex;gap:8px;overflow:auto;padding:10px 16px 2px}.category{white-space:nowrap;border:1px solid #ffffff15;border-radius:999px;background:#17233d;padding:7px 13px;color:#aeb9c9;font-size:12px;cursor:pointer}.category.active{border-color:var(--green);background:var(--green);color:#062519;font-weight:800}.products{display:grid;flex:1;grid-template-columns:repeat(auto-fill,minmax(155px,1fr));gap:12px;overflow:auto;padding:14px 16px 24px}.product{position:relative;border:1px solid #ffffff0d;border-radius:15px;background:linear-gradient(145deg,#203b64,#172b4b);padding:12px;color:#fff;text-align:left;cursor:pointer;transition:.18s}.product:hover{transform:translateY(-2px);border-color:#18c47b80;box-shadow:0 12px 24px #0003}.product .icon{display:grid;height:74px;place-items:center;border-radius:11px;background:#ffffff08;font-size:38px}.product .name{display:block;margin-top:10px;height:34px;overflow:hidden;font-size:13px;font-weight:700;line-height:1.3}.product .code{display:block;margin-top:4px;color:#8e9db1;font-size:10px}.product .bottom{display:flex;align-items:end;justify-content:space-between;margin-top:10px}.product .price{color:#55e3a5;font-size:14px;font-weight:900}.product .stock{font-size:10px;color:#c5cfdb}.product .stock.low{color:#fbbf24}.add{margin-top:10px;width:100%;border:0;border-radius:8px;background:#18c47b;padding:7px;color:#062519;font-size:11px;font-weight:900}.empty-products{grid-column:1/-1;display:grid;place-items:center;color:#8e9db1}.cart{display:flex;width:390px;flex-direction:column;border-left:1px solid #ffffff12;background:#0f3460}.customer{display:flex;align-items:center;gap:10px;background:linear-gradient(100deg,#10b981,#0ea569);padding:13px 16px}.avatar{display:grid;height:34px;width:34px;place-items:center;border-radius:50%;background:#fff3}.customer label{display:block;font-size:10px;opacity:.8}.customer input{width:100%;border:0;background:transparent;color:#fff;font-size:14px;font-weight:800;outline:0}.cart-head{display:flex;align-items:center;justify-content:space-between;background:#111827;padding:12px 16px}.cart-head h2{margin:0;font-size:15px}.clear-cart{border:0;border-radius:7px;background:#ef5350;color:#fff;padding:6px 9px;font-size:11px;font-weight:800;cursor:pointer}.cart-list{flex:1;overflow:auto;padding:10px}.cart-empty{padding:65px 15px;text-align:center;color:#8d9aae}.cart-empty .basket{font-size:42px}.line{display:flex;align-items:center;gap:8px;border-bottom:1px solid #ffffff12;padding:11px 4px}.line-info{min-width:0;flex:1}.line-info b{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px}.line-info small{display:block;margin-top:4px;color:#aab6c7;font-size:10px}.qty{display:flex;align-items:center;gap:4px}.qty button{height:24px;width:24px;border:0;border-radius:6px;background:#234c78;color:#fff;font-weight:900;cursor:pointer}.qty span{width:22px;text-align:center;font-size:12px}.line-total{font-size:12px;font-weight:900}.remove{border:0;background:none;color:#ff7373;cursor:pointer}.summary{border-top:1px solid #ffffff18;background:#16213e;padding:13px 16px}.summary-row{display:flex;justify-content:space-between;margin:6px 0;color:#bac5d4;font-size:12px}.summary-row.total{margin-top:10px;color:#fff;font-size:20px;font-weight:900}.summary-row.total b{color:#58e6a7}.pay{border:0;background:var(--green);padding:17px;color:#062519;font-size:16px;font-weight:950;cursor:pointer}.pay:disabled{cursor:not-allowed;opacity:.45}.modal{position:fixed;inset:0;z-index:20;display:none;place-items:center;background:#020617c9;padding:15px}.modal.open{display:grid}.dialog{width:min(470px,100%);border:1px solid #ffffff18;border-radius:18px;background:#17233d;padding:22px;box-shadow:0 24px 80px #0008}.dialog h2{margin:0 0 18px;font-size:19px}.methods{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.method{border:1px solid #ffffff18;border-radius:10px;background:#0f3460;padding:11px;color:#fff;cursor:pointer}.method.active{border-color:var(--green);background:var(--green);color:#062519;font-weight:900}.field{margin-top:14px}.field label{display:block;margin-bottom:6px;color:#b9c4d2;font-size:12px}.field input{width:100%;border:1px solid #ffffff12;border-radius:9px;background:#0f3460;padding:11px;color:#fff;outline:0}.quick{display:flex;gap:6px;margin-top:8px}.quick button{flex:1;border:1px solid #ffffff14;border-radius:8px;background:#203b64;padding:7px;color:#cbd5e1;font-size:11px;cursor:pointer}.totals{margin-top:16px;border-top:1px solid #ffffff18;padding-top:12px}.totals div{display:flex;justify-content:space-between;margin:7px 0;font-size:13px}.totals .grand{font-size:19px;font-weight:900}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}.cancel,.checkout{border:0;border-radius:9px;padding:11px 15px;color:#fff;font-weight:900;cursor:pointer}.cancel{background:#ef5350}.checkout{background:var(--green);color:#062519}.shortcuts{padding:7px 15px;background:#0b1220;color:#718096;font-size:10px;text-align:center}@media(max-width:850px){body{overflow:auto}.pos{height:auto;min-height:100vh;flex-direction:column}.catalog{min-height:58vh}.cart{width:auto;min-height:42vh}.top{padding:10px 12px}.top-right .user{display:none}.products{grid-template-columns:repeat(2,1fr)}}
</style></head><body><form id="sale-form" method="POST" action="{{ route('sales.store') }}">@csrf</form><div class="pos"><section class="catalog"><header class="top"><div class="brand"><span class="brand-icon">🌿</span><span><b>POS Jamu</b><small>Kasir Penjualan</small></span></div><div class="top-right"><span id="clock"></span><span class="user">{{ auth()->user()->name }}</span><a href="{{ route('dashboard') }}" class="back">← Dashboard</a></div></header><div class="tools"><input id="search" class="search" autofocus placeholder="🔍 Cari nama, kode, atau scan barcode..."><button type="button" class="clear-search" id="clear-search">×</button></div><div class="categories" id="categories"><button type="button" class="category active" data-category="all">Semua Produk</button>@foreach($products->pluck('category')->filter()->unique('id') as $category)<button type="button" class="category" data-category="{{ $category->id }}">{{ $category->name }}</button>@endforeach</div><main class="products" id="products">@forelse($products as $product)<button type="button" class="product" data-id="{{ $product->id }}" data-name="{{ $product->name }}" data-code="{{ $product->code }}" data-price="{{ $product->price }}" data-stock="{{ $product->stock }}" data-category="{{ $product->category_id }}"><span class="icon">🌿</span><span class="name">{{ $product->name }}</span><span class="code">{{ $product->code }}</span><span class="bottom"><span class="price">Rp {{ number_format($product->price,0,',','.') }}</span><span class="stock {{ $product->stock <= 5 ? 'low' : '' }}">Stok {{ $product->stock }}</span></span><span class="add">+ Tambahkan</span></button>@empty<div class="empty-products">Belum ada produk aktif.</div>@endforelse</main><div class="shortcuts">F2 Cari · F4 Bayar · F8 Kosongkan keranjang · Enter Tambah barcode</div></section><aside class="cart"><div class="customer"><span class="avatar">👤</span><div style="flex:1"><label>Customer</label><input id="customer" placeholder="Umum"></div></div><div class="cart-head"><h2>🛒 Keranjang <span id="count" style="color:#7ee8b8;font-size:11px">0 item</span></h2><button type="button" class="clear-cart" id="clear-cart">Kosongkan</button></div><div id="cart-list" class="cart-list"><div class="cart-empty"><div class="basket">🛒</div><p>Keranjang masih kosong</p><small>Pilih produk untuk memulai transaksi</small></div></div><div class="summary"><div class="summary-row"><span>Subtotal</span><b id="subtotal">Rp 0</b></div><div class="summary-row"><span>Diskon</span><b id="discount-label">Rp 0</b></div><div class="summary-row total"><span>Total</span><b id="total">Rp 0</b></div></div><button class="pay" type="button" id="pay" disabled>💳 BAYAR <span style="font-size:11px">(F4)</span></button></aside></div><div class="modal" id="modal"><div class="dialog"><h2>🧾 Pembayaran <small style="color:#8eeac0;font-size:13px">· <span id="modal-customer">Umum</span></small></h2><div class="methods"><button type="button" class="method active" data-method="cash">💵 Tunai</button><button type="button" class="method" data-method="qris">▣ QRIS</button><button type="button" class="method" data-method="transfer">⇄ Transfer</button></div><div class="field"><label>Diskon</label><input id="discount" type="number" min="0" value="0"></div><div class="field"><label>Jumlah pembayaran</label><input id="paid" type="number" min="0" placeholder="Masukkan nominal" autofocus><div class="quick"><button type="button" data-quick="exact">Uang pas</button><button type="button" data-quick="10000">Rp10.000</button><button type="button" data-quick="20000">Rp20.000</button><button type="button" data-quick="50000">Rp50.000</button></div></div><div class="totals"><div><span>Subtotal</span><b id="m-subtotal">Rp 0</b></div><div><span>Diskon</span><b id="m-discount">Rp 0</b></div><div class="grand"><span>Total</span><b id="m-total">Rp 0</b></div><div><span>Kembalian</span><b id="change">Rp 0</b></div></div><div class="actions"><button type="button" class="cancel" id="cancel">Batal</button><button type="button" class="checkout" id="checkout">✅ Checkout</button></div></div></div><script>
let cart=[],method='cash',submitting=false;const money=n=>'Rp '+new Intl.NumberFormat('id-ID').format(n||0),$=id=>document.getElementById(id),subtotal=()=>cart.reduce((s,x)=>s+x.price*x.qty,0),grand=()=>Math.max(0,subtotal()-(+$('discount').value||0));function render(){let count=cart.reduce((s,x)=>s+x.qty,0);$('count').textContent=count+' item';$('cart-list').innerHTML=cart.length?cart.map(x=>`<div class="line"><div class="qty"><button type="button" data-minus="${x.id}">−</button><span>${x.qty}</span><button type="button" data-plus="${x.id}">+</button></div><div class="line-info"><b>${x.name}</b><small>${money(x.price)} × ${x.qty}</small></div><span class="line-total">${money(x.price*x.qty)}</span><button type="button" class="remove" data-remove="${x.id}">×</button></div>`).join(''):'<div class="cart-empty"><div class="basket">🛒</div><p>Keranjang masih kosong</p><small>Pilih produk untuk memulai transaksi</small></div>';$('subtotal').textContent=money(subtotal());$('discount-label').textContent=money(+$('discount').value||0);$('total').textContent=money(grand());$('m-subtotal').textContent=money(subtotal());$('m-discount').textContent=money(+$('discount').value||0);$('m-total').textContent=money(grand());$('change').textContent=money(Math.max(0,(+$('paid').value||0)-grand()));$('pay').disabled=!cart.length;document.querySelectorAll('[data-minus]').forEach(b=>b.onclick=()=>adjust(+b.dataset.minus,-1));document.querySelectorAll('[data-plus]').forEach(b=>b.onclick=()=>adjust(+b.dataset.plus,1));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart=cart.filter(x=>x.id!==+b.dataset.remove);render()})}function adjust(id,n){let x=cart.find(x=>x.id===id);if(x){x.qty=Math.max(1,Math.min(x.stock,x.qty+n));render()}}document.querySelectorAll('.product').forEach(p=>p.onclick=()=>{let x={id:+p.dataset.id,name:p.dataset.name,price:+p.dataset.price,stock:+p.dataset.stock,qty:1},old=cart.find(i=>i.id===x.id);old?old.qty=Math.min(old.stock,old.qty+1):cart.push(x);render();$('search').focus()});function filter(){let q=$('search').value.toLowerCase(),cat=document.querySelector('.category.active').dataset.category;document.querySelectorAll('.product').forEach(p=>p.style.display=((p.dataset.name+' '+p.dataset.code).toLowerCase().includes(q)&&(cat==='all'||p.dataset.category===cat))?'block':'none')}$('search').oninput=filter;$('clear-search').onclick=()=>{$('search').value='';filter();$('search').focus()};document.querySelectorAll('.category').forEach(b=>b.onclick=()=>{document.querySelectorAll('.category').forEach(x=>x.classList.remove('active'));b.classList.add('active');filter()});$('clear-cart').onclick=()=>{if(cart.length&&confirm('Kosongkan semua isi keranjang?')){cart=[];render()}};$('pay').onclick=()=>{if(cart.length){$('modal-customer').textContent=$('customer').value||'Umum';$('modal').classList.add('open');$('paid').focus();render()}};$('cancel').onclick=()=>$('modal').classList.remove('open');document.querySelectorAll('.method').forEach(b=>b.onclick=()=>{method=b.dataset.method;document.querySelectorAll('.method').forEach(x=>x.classList.toggle('active',x===b))});$('discount').oninput=$('paid').oninput=render;document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>{$('paid').value=b.dataset.quick==='exact'?grand():b.dataset.quick;render()});$('checkout').onclick=()=>{if(submitting)return;if((+$('paid').value||0)<grand()){alert('Jumlah pembayaran kurang dari total.');return}submitting=true;let f=$('sale-form');f.insertAdjacentHTML('beforeend',`<input name="customer_name" value="${$('customer').value}"><input name="discount" value="${$('discount').value||0}"><input name="payment_method" value="${method}"><input name="paid_amount" value="${$('paid').value}">`+cart.map((x,i)=>`<input name="items[${i}][product_id]" value="${x.id}"><input name="items[${i}][quantity]" value="${x.qty}">`).join(''));f.submit()};document.addEventListener('keydown',e=>{if(e.key==='F2'){e.preventDefault();$('search').focus()}if(e.key==='F4'){e.preventDefault();if(cart.length)$('pay').click()}if(e.key==='F8'){e.preventDefault();$('clear-cart').click()}if(e.key==='Escape')$('modal').classList.remove('open');if(e.key==='Enter'&&document.activeElement===$('search')){let visible=[...document.querySelectorAll('.product')].find(p=>p.style.display!=='none');if(visible)visible.click()}});setInterval(()=>$('clock').textContent=new Date().toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'}),1000);render();
</script><script>
const customerDirectory=@json($customers->map(fn($customer)=>['id'=>$customer->id,'name'=>$customer->name,'code'=>$customer->member_code])->values());const customerInput=document.getElementById('customer');const saleForm=document.getElementById('sale-form');if(customerInput&&customerDirectory.length){const list=document.createElement('datalist');list.id='customer-list';customerDirectory.forEach(c=>{const option=document.createElement('option');option.value=c.name;option.label=c.code;list.appendChild(option)});document.body.appendChild(list);customerInput.setAttribute('list','customer-list');const hidden=document.createElement('input');hidden.type='hidden';hidden.name='customer_id';saleForm.appendChild(hidden);const syncCustomer=()=>{const match=customerDirectory.find(c=>c.name.toLowerCase()===customerInput.value.trim().toLowerCase());hidden.value=match?.id||''};customerInput.addEventListener('input',syncCustomer)}
</script><script>
const productBarcodes=@json($products->mapWithKeys(fn($product)=>[$product->id=>$product->barcode])->toArray());const searchInput=document.getElementById('search');if(searchInput){searchInput.addEventListener('input',()=>{const q=searchInput.value.toLowerCase();const category=document.querySelector('.category.active')?.dataset.category||'all';document.querySelectorAll('.product').forEach(product=>{const barcode=(productBarcodes[product.dataset.id]||'').toLowerCase();const match=(product.dataset.name+' '+product.dataset.code+' '+barcode).toLowerCase().includes(q);product.style.display=match&&(category==='all'||product.dataset.category===category)?'block':'none'})})}
</script></body></html>
